		}
		checkpoints, discoverWarnings, err := discoverCheckpoints(ctx, opts.Runner, repoDir, exportOpts.entireBinary, exportOpts.scope, exportOpts.checkpointLimit)
		if err != nil {
			return err
		}
		warnings = append(warnings, discoverWarnings...)
