func withBrainManifestWriteLock(brainDir string, fn func() error) error {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(brainDir, brainLockDirName); err != nil {
