	resetOpts := semanticResetOptions{}
	cmd := &cobra.Command{
		Use:   "reset [path]",
		Short: "Remove local generated brain data",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			target := "."
			if opts.Env.RepoRoot != "" {
