		return fmt.Errorf("recreate brain write lock metadata: %w", err)
	} else {
		writeLockMetadata(f)
		if err := f.Close(); err != nil {
			return fmt.Errorf("close brain write lock metadata: %w", err)
		}
	}
	fmt.Fprintf(cmd.OutOrStdout(), "reset brain: %s\n", storage.BrainDir)
	return nil
}

