		for i, k := range kinds {
			placeholders[i] = "?"
			*args = append(*args, k)
		}
		sb.WriteString(" AND " + column + " IN (" + strings.Join(placeholders, ",") + ")")
		return
	}
	sb.WriteString(" AND " + column + " NOT IN ('request', ?)")
	*args = append(*args, conversationKind)
}

