+func prepareHistoryFTSTargetForReplacement(path string) error {
+	if err := rejectUnsafeExistingRegularFile(path, "history sqlite cache"); err != nil {
+		return err
+	}
+	_, err := os.Lstat(path)
+	if err != nil && !os.IsNotExist(err) {
+		return err
+	}
+	if err == nil {
+		db, openErr := sql.Open(sqliteDriverName, path)
+		if openErr == nil {
+			db.SetMaxOpenConns(1)
+			_, _ = db.Exec(`PRAGMA busy_timeout=5000;`)
+			var integrity string
+			integrityErr := db.QueryRow(`PRAGMA integrity_check`).Scan(&integrity)
+			if integrityErr == nil && integrity == "ok" {
+				var mode string
+				modeErr := db.QueryRow(`PRAGMA journal_mode=DELETE`).Scan(&mode)
+				closeErr := db.Close()
+				if modeErr != nil {
+					modeErr = fmt.Errorf("prepare old history fts journal: %w", modeErr)
+				}
+				if err := errors.Join(modeErr, closeErr); err != nil {
+					return err
+				}
+				if !strings.EqualFold(mode, "delete") {
+					return fmt.Errorf("prepare old history fts journal: mode is %q, want delete", mode)
+				}
+			} else if closeErr := db.Close(); closeErr != nil {
+				return closeErr
+			}
+		}
+	}
+	return removeHistoryFTSArtifacts(path, false)
