+// removeHistoryFTSArtifacts removes SQLite sidecars and, for a private staging
+// path, the main database. Every path is exact; no glob can widen cleanup.
+func removeHistoryFTSArtifacts(path string, removeMain bool) error {
+	paths := make([]string, 0, len(historyFTSSidecarSuffixes)+1)
+	if removeMain {
+		paths = append(paths, path)
+	}
+	for _, suffix := range historyFTSSidecarSuffixes {
+		paths = append(paths, path+suffix)
+	}
+	var cleanupErr error
+	for _, candidate := range paths {
+		if err := rejectUnsafeExistingRegularFile(candidate, "history sqlite artifact"); err != nil {
+			cleanupErr = errors.Join(cleanupErr, err)
+			continue
+		}
+		if err := os.Remove(candidate); err != nil && !os.IsNotExist(err) {
+			cleanupErr = errors.Join(cleanupErr, err)
+		}
+	}
+	return cleanupErr
+}
