package cli

import (
	"context"
	"reflect"
	"strings"
	"testing"
	"time"
)

func TestReconcileHistoryRecordIDsSuppressesByteEquivalentDuplicates(t *testing.T) {
	first := historyRecord{
		ID:      "history:shared",
		Kind:    "code_fact",
		Path:    "sessions/main/first.jsonl",
		Line:    7,
		Summary: "the canonical payload",
	}
	byteEquivalent := first
	byteEquivalent.Terms = []string{}
	byteEquivalent.ToolNames = []string{}

	got, err := reconcileHistoryRecordIDs([]historyRecord{first, byteEquivalent})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, []historyRecord{first}) {
		t.Fatalf("reconciled records = %#v, want first byte-equivalent payload only", got)
	}
}

func TestReconcileHistoryRecordIDsRejectsConflictingPayloads(t *testing.T) {
	records := []historyRecord{
		{ID: "history:collision", Kind: "code_fact", Path: "sessions/main/a.jsonl", Line: 3, Summary: "first payload"},
		{ID: "history:collision", Kind: "code_fact", Path: "sessions/main/b.jsonl", Line: 8, Summary: "different payload"},
	}

	got, err := reconcileHistoryRecordIDs(records)
	if err == nil {
		t.Fatalf("reconciled records = %#v, want an explicit collision error", got)
	}
	if !strings.Contains(err.Error(), `history record ID collision for "history:collision"`) ||
		!strings.Contains(err.Error(), "different payloads") {
		t.Fatalf("collision error = %q", err)
	}
}

func TestReconcileHistoryRecordIDsPreservesFirstOccurrenceAndOrder(t *testing.T) {
	first := historyRecord{ID: "history:first", Kind: "decision", Path: "a", Line: 1, Summary: "first"}
	second := historyRecord{ID: "history:second", Kind: "learning", Path: "b", Line: 2, Summary: "second"}
	third := historyRecord{ID: "history:third", Kind: "validation", Path: "c", Line: 3, Summary: "third"}

	got, err := reconcileHistoryRecordIDs([]historyRecord{first, second, first, third, second})
	if err != nil {
		t.Fatal(err)
	}
	want := []historyRecord{first, second, third}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("reconciled records = %#v, want %#v", got, want)
	}
}

func TestReconcileHistoryRecordIDsKeepsEmptyIDsDistinct(t *testing.T) {
	legacy := historyRecord{Kind: "code_fact", Path: "legacy.jsonl", Line: 1, Summary: "legacy payload"}
	records := []historyRecord{legacy, legacy}

	got, err := reconcileHistoryRecordIDs(records)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, records) {
		t.Fatalf("reconciled records = %#v, want both empty-ID records %#v", got, records)
	}
}

func TestHistoryIndexManifestReflectsReconciledRecords(t *testing.T) {
	now := time.Date(2026, 8, 20, 12, 0, 0, 0, time.UTC)
	transcript := `{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"const canonicalValue = 7"},{"type":"tool_result","content":"const canonicalValue = 7"}]}}` + "\n"
	raw, err := scanHistoryLines(context.Background(), "sessions/main/s1.jsonl", ".jsonl", strings.NewReader(transcript))
	if err != nil {
		t.Fatal(err)
	}
	if len(raw) != 2 || raw[0].ID != raw[1].ID {
		t.Fatalf("fixture produced records %#v, want two records with the same stable ID", raw)
	}
	brainDir := writeSingleSessionFixture(t, now, transcript)

	source, err := writeBrainHistoryIndexAndSource(brainDir, now, nil)
	if err != nil {
		t.Fatal(err)
	}
	index, err := loadBrainHistoryIndex(brainDir, source)
	if err != nil {
		t.Fatal(err)
	}
	if len(index.Records) != 1 || source.Records != 1 || source.CodeFacts != 1 {
		t.Fatalf("deduped index/manifest = %d records, source %+v", len(index.Records), source)
	}
	if got, want := source.RecordsFingerprint, historyRecordsFingerprint(index.Records); got == "" || got != want {
		t.Fatalf("records fingerprint = %q, want %q", got, want)
	}
}
package cli

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"

	"github.com/spf13/cobra"
)

const (
	historyDirName           = "history"
	historyIndexFileName     = "index.json"
	historyIndexPath         = historyDirName + "/" + historyIndexFileName
	historyGenerationsDir    = historyDirName + "/generations"
	historyStagingDir        = historyDirName + "/staging"
	historyScanCacheFileName = "scan-cache.json.gz"
	historyScanCachePath     = historyDirName + "/" + historyScanCacheFileName
	historyMaxLineBytes      = 1024 * 1024
	// historyScanCacheVersion gates reuse of cached per-file scan results.
	// Bump it whenever the history record extraction/classification logic
	// changes so stale cached records are discarded on the next refresh.
	// v2: index user prompts as "request" records.
	// v3: stop EXTRACTING request records during scan (the v2 indexing) — they were
	// excluded from general ranking (measured noise) and the only surfaces that
	// could query them (inspect requests / brain_history kind=requests) were
	// removed. The request-kind gates/filtering are kept as defensive support for
	// stale indexes; bumping discards per-file scan caches that still hold request
	// records so they stop reappearing on refresh.
	// v4: RE-introduce request extraction (wrapper-filtered, via
	// transcriptUserText). Two Phase 2 consumers reopened the v3 closed
	// question with new evidence: `brief --handoff` needs each session's
	// opening request and the history eval's midtask stratum mines follow-up
	// questions as queries. The v3 noise concern is unchanged and unaffected:
	// both rankers still exclude kind=request from general ranking.
	// v5: extract experimental conversation "exchange" records (conversation.go)
	// during the scan; older caches do not contain them.
	// v6: conversation-scoped wrapper filtering (hook-injected pseudo-requests)
	// and API-error narrative exclusion changed exchange extraction; cached v5
	// exchanges would keep the noise.
	// v7: bind cache reuse to the transcript content digest; size+mtime alone
	// misses atomic same-metadata leaf replacement.
	// v8: TWO independent v7 formats were developed in parallel (one keyed on
	// content_digest from the descriptor-rooted inventory, one on content_sha256
	// with pre-annotation raw records). They are deliberately invalidated rather
	// than guessed apart, exactly as the two v6 formats were.
	// v9: two independent v8s merged. One lineage's v8 switched code-fact
	// extraction from a fixed phrase list to the structural signal
	// (declarations, documented flag defaults, literal assignments, file:line
	// anchors) with a matching pre-decode line filter; the other's v8 was the
	// parallel-format invalidation above. A warm v8 cache from either lineage
	// would silently keep that lineage's behavior, so both are invalidated.
	historyScanCacheVersion = 9
)

type historySourceManifest struct {
	GeneratedAt time.Time `json:"generated_at"`
	IndexPath   string    `json:"index_path"`
	// IndexBytes/IndexSHA256/RecordsFingerprint let a reader rank straight from
	// the FTS payload table without loading index.json, and give the FTS
	// freshness check an O(1) key.
	IndexBytes             int64  `json:"index_bytes,omitempty"`
	IndexSHA256            string `json:"index_sha256,omitempty"`
	RecordsFingerprint     string `json:"records_fingerprint,omitempty"`
	TranscriptsFingerprint string `json:"transcripts_fingerprint,omitempty"`

