// reconcileHistoryRecordIDs makes the canonical index safe for consumers that
// address records by their stable ID. Exact duplicate payloads can arise when
// one logical record is exported more than once; retain the first copy without
// disturbing record order. The same non-empty ID on different payloads is an
// identity collision and must stop publication rather than pick a winner.
// Records without an ID predate stable identity and remain physically distinct.
func reconcileHistoryRecordIDs(records []historyRecord) ([]historyRecord, error) {
	seen := make(map[string]int, len(records))
	for i, record := range records {
		if record.ID == "" {
			continue
		}
		first, duplicate := seen[record.ID]
		if !duplicate {
			seen[record.ID] = i
			continue
		}

		firstPayload, err := json.Marshal(records[first])
		if err != nil {
			return nil, fmt.Errorf("encode history record %q for ID reconciliation: %w", record.ID, err)
		}
		duplicatePayload, err := json.Marshal(record)
		if err != nil {
			return nil, fmt.Errorf("encode duplicate history record %q for ID reconciliation: %w", record.ID, err)
		}
		if !bytes.Equal(firstPayload, duplicatePayload) {
			return nil, fmt.Errorf("history record ID collision for %q: records %d and %d have different payloads", record.ID, first+1, i+1)
		}
	}

	write := 0
	for i, record := range records {
		if record.ID != "" && seen[record.ID] != i {
			continue
		}
		records[write] = record
		write++
	}
	clear(records[write:])
	return records[:write], nil
}

