	var payloadRows, ftsRows int
	if err := db.QueryRow(`SELECT count(*) FROM history_records`).Scan(&payloadRows); err != nil {
		return fmt.Errorf("history fts payload count: %w", err)
	}
	if err := db.QueryRow(`SELECT count(*) FROM history_fts`).Scan(&ftsRows); err != nil {
		return fmt.Errorf("history fts row count: %w", err)
	}
	if payloadRows != identity.RecordCount || ftsRows != identity.RecordCount {
		return fmt.Errorf("history fts validation: row count payload=%d fts=%d want=%d", payloadRows, ftsRows, identity.RecordCount)
	}
	return nil
}

func syncHistoryFTSStaging(path string) error {
	f, err := os.OpenFile(path, os.O_RDWR|fileLockOpenFlags(), 0)
	if err != nil {
		return fmt.Errorf("open history fts staging database for sync: %w", err)
	}
	if err := rejectOpenFileAlias(path, f, "history fts staging database"); err != nil {
		_ = f.Close()
		return err
	}
	syncErr := f.Sync()
	closeErr := f.Close()
	if syncErr != nil {
		syncErr = fmt.Errorf("sync history fts staging database: %w", syncErr)
	}
	return errors.Join(syncErr, closeErr)
}

func decodeHistoryFTSPublication(data []byte) (historyFTSPublication, error) {
	var publication historyFTSPublication
	if err := json.Unmarshal(data, &publication); err != nil {
		return publication, fmt.Errorf("decode history FTS publication marker: %w", err)
	}
	candidateHex := strings.TrimPrefix(publication.Candidate, historyFTSStagingPrefix)
	candidateID, candidateErr := hex.DecodeString(candidateHex)
	digest, digestErr := hex.DecodeString(publication.SHA256)
	if publication.SchemaVersion != historyFTSPublicationVersion ||
		!strings.HasPrefix(publication.Candidate, historyFTSStagingPrefix) || len(candidateID) != 16 || candidateErr != nil ||
		len(digest) != sha256.Size || digestErr != nil || publication.Size < 1 || publication.Size > privacySQLiteSnapshotMaxBytes {
		return historyFTSPublication{}, fmt.Errorf("%s: invalid history FTS publication marker", memoryErrStateUnsafe)
	}
	return publication, nil
}

func readPinnedHistoryFTSPublication(pinned *pinnedHistoryFTSDirectory) (historyFTSPublication, os.FileInfo, error) {
	var publication historyFTSPublication
	info, present, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker")
	if err != nil {
		return publication, nil, err
	}
	if !present || info.Size() < 1 || info.Size() > historyFTSPublicationMarkerMax {
		return publication, nil, fmt.Errorf("%s: history FTS publication marker is missing or malformed", memoryErrStateUnsafe)
	}
	if err := verifyPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker", info); err != nil {
		return publication, nil, err
	}
	marker, err := pinned.historyRoot.OpenFile(historyFTSPublicationMarkerName, os.O_RDONLY|fileLockOpenFlags()|memoryStateReadOpenFlags(), 0)
	if err != nil {
		return publication, nil, err
	}
	data, readErr := io.ReadAll(io.LimitReader(marker, historyFTSPublicationMarkerMax+1))
	closeErr := marker.Close()
	if readErr != nil || closeErr != nil || len(data) > historyFTSPublicationMarkerMax {
		return publication, nil, errors.Join(readErr, closeErr, fmt.Errorf("%s: read bounded history FTS publication marker", memoryErrStateUnsafe))
	}
	current, stillPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker")
	if err != nil || !stillPresent || !os.SameFile(info, current) || current.Size() != info.Size() || !current.ModTime().Equal(info.ModTime()) {
		return publication, nil, fmt.Errorf("%s: history FTS publication marker changed while reading", memoryErrStateUnsafe)
	}
	publication, err = decodeHistoryFTSPublication(data)
	if err != nil {
		return historyFTSPublication{}, nil, err
	}
	return publication, info, nil
}

func validatePinnedHistoryFTSDatabase(root *os.Root, name string, publication historyFTSPublication) (os.FileInfo, error) {
	info, present, err := inspectPinnedHistoryFTSLeaf(root, name, "history FTS publication database")
	if err != nil {
		return nil, err
	}
	if !present || info.Size() != publication.Size {
		return nil, fmt.Errorf("%s: history FTS publication database is missing or changed", memoryErrStateUnsafe)
	}
	f, err := root.OpenFile(name, os.O_RDONLY|fileLockOpenFlags()|memoryStateReadOpenFlags(), 0)
	if err != nil {
		return nil, err
	}
	opened, statErr := f.Stat()
	if statErr != nil || !os.SameFile(info, opened) {
		_ = f.Close()
		return nil, fmt.Errorf("%s: history FTS publication database changed while opening", memoryErrStateUnsafe)
	}
	if err := rejectOpenFileHardlink(name, f, opened, "history FTS publication database"); err != nil {
		_ = f.Close()
		return nil, fmt.Errorf("%s: %w", memoryErrStateUnsafe, err)
	}
	hash := sha256.New()
	copied, copyErr := io.Copy(hash, io.LimitReader(f, privacySQLiteSnapshotMaxBytes+1))
	after, afterErr := f.Stat()
	closeErr := f.Close()
	current, currentPresent, currentErr := inspectPinnedHistoryFTSLeaf(root, name, "history FTS publication database")
	if copyErr != nil || afterErr != nil || closeErr != nil || currentErr != nil || !currentPresent || copied != publication.Size ||
		!os.SameFile(info, after) || !os.SameFile(info, current) || after.Size() != info.Size() || !after.ModTime().Equal(info.ModTime()) ||
		hex.EncodeToString(hash.Sum(nil)) != publication.SHA256 {
		return nil, fmt.Errorf("%s: history FTS publication database failed its durable digest", memoryErrStateUnsafe)
	}
	return info, nil
}

func inspectPinnedHistoryFTSPublicationInputs(pinned *pinnedHistoryFTSDirectory) (os.FileInfo, bool, map[string]os.FileInfo, error) {
	targetInfo, targetPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database")
	if err != nil {
		return nil, false, nil, err
	}
	if targetPresent {
		if err := verifyPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database", targetInfo); err != nil {
			return nil, false, nil, err
		}
	}
	sidecars := make(map[string]os.FileInfo, len(historyFTSSidecarSuffixes))
	for _, name := range historyFTSSidecarNames() {
		info, present, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, name, "history FTS sidecar "+name)
		if err != nil {
			return nil, false, nil, err
		}
		if present {
			if err := verifyPinnedHistoryFTSLeaf(pinned.historyRoot, name, "history FTS sidecar "+name, info); err != nil {
				return nil, false, nil, err
			}
			sidecars[name] = info
		} else {
			sidecars[name] = nil
		}
	}
	return targetInfo, targetPresent, sidecars, nil
}

func verifyPinnedHistoryFTSTargetUnchanged(pinned *pinnedHistoryFTSDirectory, expected os.FileInfo, expectedPresent bool) error {
	current, present, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database")
	if err != nil {
		return err
	}
	if present != expectedPresent || present && (!os.SameFile(expected, current) || current.Size() != expected.Size() || !current.ModTime().Equal(expected.ModTime())) {
		return fmt.Errorf("%s: live history FTS database changed before publication", memoryErrStateUnsafe)
	}
	if present {
		return verifyPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database", current)
	}
	return nil
}

func removePinnedHistoryFTSSidecars(pinned *pinnedHistoryFTSDirectory, expected map[string]os.FileInfo, useHooks bool) error {
	for _, name := range historyFTSSidecarNames() {
		if useHooks {
			if err := historyFTSPublishBoundary("before_remove_" + name); err != nil {
				return err
			}
		}
		info, present, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, name, "history FTS sidecar "+name)
		if err != nil {
			return err
		}
		if expected != nil {
			want := expected[name]
			if (want != nil) != present || present && (!os.SameFile(want, info) || info.Size() != want.Size() || !info.ModTime().Equal(want.ModTime())) {
				return fmt.Errorf("%s: history FTS sidecar changed before removal: %s", memoryErrStateUnsafe, name)
			}
		}
		if present {
			if err := verifyPinnedHistoryFTSLeaf(pinned.historyRoot, name, "history FTS sidecar "+name, info); err != nil {
				return err
			}
			if err := pinned.historyRoot.Remove(name); err != nil {
				return fmt.Errorf("remove history FTS sidecar %s: %w", name, err)
			}
		}
		if useHooks {
			if err := historyFTSPublishBoundary("after_remove_" + name); err != nil {
				return err
			}
		}
	}
	return nil
}

// recoverHistoryFTSPublicationLocked completes a marked publication. A marker
// names and hashes the already-validated candidate, so recovery never asks
// SQLite to open a pathname beneath a replaceable Brain directory.
func recoverHistoryFTSPublicationLocked(brainDir string) error {
	pinned, present, err := openPinnedHistoryFTSDirectory(brainDir, false)
	if err != nil || !present {
		return err
	}
	defer pinned.Close()
	_, markerPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker")
	if err != nil || !markerPresent {
		return err
	}
	publication, markerInfo, err := readPinnedHistoryFTSPublication(pinned)
	if err != nil {
		return err
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	candidateInfo, candidatePresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, publication.Candidate, "history FTS recovery candidate")
	if err != nil {
		return err
	}
	if candidatePresent {
		candidateInfo, err = validatePinnedHistoryFTSDatabase(pinned.historyRoot, publication.Candidate, publication)
	} else {
		candidateInfo, err = validatePinnedHistoryFTSDatabase(pinned.historyRoot, historyFTSFileName, publication)
	}
	if err != nil {
		return err
	}
	// A current target may be old or may already be the new digest. It must at
	// least remain a stable, non-aliased regular leaf before recovery replaces it.
	if targetInfo, targetPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database"); err != nil {
		return err
	} else if targetPresent {
		if err := verifyPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSFileName, "live history FTS database", targetInfo); err != nil {
			return err
		}
	}
	if err := removePinnedHistoryFTSSidecars(pinned, nil, false); err != nil {
		return err
	}
	if candidatePresent {
		current, stillPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, publication.Candidate, "history FTS recovery candidate")
		if err != nil || !stillPresent || !os.SameFile(candidateInfo, current) {
			return fmt.Errorf("%s: history FTS recovery candidate changed before rename", memoryErrStateUnsafe)
		}
		if err := pinned.historyRoot.Rename(publication.Candidate, historyFTSFileName); err != nil {
			return fmt.Errorf("recover pinned history FTS database: %w", err)
		}
	}
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync recovered history FTS database: %w", err)
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	if _, err := validatePinnedHistoryFTSDatabase(pinned.historyRoot, historyFTSFileName, publication); err != nil {
		return err
	}
	currentMarker, stillMarked, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker")
	if err != nil || !stillMarked || !os.SameFile(markerInfo, currentMarker) {
		return fmt.Errorf("%s: history FTS publication marker changed before recovery commit", memoryErrStateUnsafe)
	}
	if err := pinned.historyRoot.Remove(historyFTSPublicationMarkerName); err != nil {
		return fmt.Errorf("remove recovered history FTS publication marker: %w", err)
	}
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync recovered history FTS marker removal: %w", err)
	}
	return pinned.validate()
}

func publishHistoryFTSStagingLocked(brainDir, stagingPath string) error {
	staging, err := os.Open(stagingPath)
	if err != nil {
		return err
	}
	defer staging.Close()
	stagingInfo, err := staging.Stat()
	if err != nil || !stagingInfo.Mode().IsRegular() || stagingInfo.Size() < 1 || stagingInfo.Size() > privacySQLiteSnapshotMaxBytes {
		return fmt.Errorf("%s: invalid staged history FTS database", memoryErrStateUnsafe)
	}
	pinned, _, err := openPinnedHistoryFTSDirectory(brainDir, true)
	if err != nil {
		return err
	}
	defer pinned.Close()
	if _, markerPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker"); err != nil || markerPresent {
		if err != nil {
			return err
		}
		return fmt.Errorf("%s: history FTS publication marker unexpectedly exists", memoryErrStateUnsafe)
	}
	targetInfo, targetPresent, sidecars, err := inspectPinnedHistoryFTSPublicationInputs(pinned)
	if err != nil {
		return err
	}

	var random [16]byte
	if _, err := rand.Read(random[:]); err != nil {
		return err
	}
	candidateName := historyFTSStagingPrefix + hex.EncodeToString(random[:])
	candidate, err := pinned.historyRoot.OpenFile(candidateName, os.O_WRONLY|os.O_CREATE|os.O_EXCL|fileLockOpenFlags(), 0o600)
	if err != nil {
		return fmt.Errorf("%s: create pinned history FTS candidate: %w", memoryErrStateUnsafe, err)
	}
	removeCandidate := true
	defer func() {
		_ = candidate.Close()
		if removeCandidate {
			_ = pinned.historyRoot.Remove(candidateName)
		}
	}()
	hash := sha256.New()
	copied, copyErr := io.Copy(io.MultiWriter(candidate, hash), io.LimitReader(staging, privacySQLiteSnapshotMaxBytes+1))
	afterStaging, statErr := staging.Stat()
	if copyErr != nil || statErr != nil || copied != stagingInfo.Size() || copied > privacySQLiteSnapshotMaxBytes || !os.SameFile(stagingInfo, afterStaging) || afterStaging.Size() != stagingInfo.Size() || !afterStaging.ModTime().Equal(stagingInfo.ModTime()) {
		return fmt.Errorf("%s: staged history FTS database changed during publication", memoryErrStateUnsafe)
	}
	if err := candidate.Sync(); err != nil {
		return fmt.Errorf("sync pinned history FTS candidate: %w", err)
	}
	if err := candidate.Close(); err != nil {
		return fmt.Errorf("close pinned history FTS candidate: %w", err)
	}
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync history FTS candidate directory entry: %w", err)
	}
	publication := historyFTSPublication{
		SchemaVersion: historyFTSPublicationVersion,
		Candidate:     candidateName,
		SHA256:        hex.EncodeToString(hash.Sum(nil)),
		Size:          copied,
	}
	if _, err := validatePinnedHistoryFTSDatabase(pinned.historyRoot, candidateName, publication); err != nil {
		return err
	}
	if err := historyFTSPublishBoundary("before_marker_create"); err != nil {
		return err
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	markerData, err := json.Marshal(publication)
	if err != nil {
		return err
	}
	markerData = append(markerData, '\n')
	marker, err := pinned.historyRoot.OpenFile(historyFTSPublicationMarkerName, os.O_WRONLY|os.O_CREATE|os.O_EXCL|fileLockOpenFlags(), 0o600)
	if err != nil {
		return fmt.Errorf("%s: create history FTS publication marker: %w", memoryErrStateUnsafe, err)
	}
	written, writeErr := marker.Write(markerData)
	syncErr := marker.Sync()
	closeErr := marker.Close()
	if writeErr != nil || syncErr != nil || closeErr != nil || written != len(markerData) {
		_ = pinned.historyRoot.Remove(historyFTSPublicationMarkerName)
		return errors.Join(writeErr, syncErr, closeErr, errors.New("write durable history FTS publication marker"))
	}
	// The marker may survive even if directory sync reports an error, so retain
	// the candidate from this point onward for deterministic recovery.
	removeCandidate = false
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync history FTS publication marker: %w", err)
	}
	if err := historyFTSPublishBoundary("after_marker_create"); err != nil {
		return err
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	if err := removePinnedHistoryFTSSidecars(pinned, sidecars, true); err != nil {
		return err
	}
	if err := historyFTSPublishBoundary("before_main_rename"); err != nil {
		return err
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	if err := verifyPinnedHistoryFTSTargetUnchanged(pinned, targetInfo, targetPresent); err != nil {
		return err
	}
	if err := pinned.historyRoot.Rename(candidateName, historyFTSFileName); err != nil {
		return fmt.Errorf("publish pinned history FTS database: %w", err)
	}
	if err := historyFTSPublishBoundary("after_main_rename"); err != nil {
		return err
	}
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync published history FTS database: %w", err)
	}
	if err := historyFTSPublishBoundary("after_main_sync"); err != nil {
		return err
	}
	if err := pinned.validate(); err != nil {
		return err
	}
	if _, err := validatePinnedHistoryFTSDatabase(pinned.historyRoot, historyFTSFileName, publication); err != nil {
		return err
	}
	currentPublication, markerInfo, err := readPinnedHistoryFTSPublication(pinned)
	if err != nil || currentPublication != publication {
		return fmt.Errorf("%s: history FTS publication marker changed before commit", memoryErrStateUnsafe)
	}
	if err := historyFTSPublishBoundary("before_marker_remove"); err != nil {
		return err
	}
	currentMarker, markerPresent, err := inspectPinnedHistoryFTSLeaf(pinned.historyRoot, historyFTSPublicationMarkerName, "history FTS publication marker")
	if err != nil || !markerPresent || !os.SameFile(markerInfo, currentMarker) {
		return fmt.Errorf("%s: history FTS publication marker changed before removal", memoryErrStateUnsafe)
	}
	if err := pinned.historyRoot.Remove(historyFTSPublicationMarkerName); err != nil {
		return fmt.Errorf("commit history FTS publication: %w", err)
	}
	if err := syncPinnedDirectory(pinned.historyRoot); err != nil {
		return fmt.Errorf("sync history FTS publication commit: %w", err)
	}
	return pinned.validate()
}

// rebuildHistoryFTSFromTruth force-replaces a corrupt derived payload after the
// authoritative JSON index has been verified and loaded. Normal stale caches use
// openHistoryFTS's cheaper double-checked rebuild; this path is only for a v3
// database whose metadata claimed freshness but whose hydrated rows were invalid.
func rebuildHistoryFTSFromTruth(brainDir string, index historyIndex) error {
