func (p *pinnedHistoryFTSDirectory) validate() error {
	currentBrain, err := os.Lstat(p.brainDir)
	if err != nil || currentBrain.Mode()&os.ModeSymlink != 0 || !os.SameFile(p.brainInfo, currentBrain) {
		return fmt.Errorf("%s: Brain root changed during history FTS publication", memoryErrStateUnsafe)
	}
	pinnedBrain, err := p.root.Stat(".")
	if err != nil || !pinnedBrain.IsDir() || !os.SameFile(p.brainInfo, pinnedBrain) {
		return fmt.Errorf("%s: pinned Brain root changed during history FTS publication", memoryErrStateUnsafe)
	}
	currentHistory, err := p.root.Lstat(historyDirName)
	if err != nil || currentHistory.Mode()&os.ModeSymlink != 0 || !os.SameFile(p.historyInfo, currentHistory) {
		return fmt.Errorf("%s: history FTS directory changed during publication", memoryErrStateUnsafe)
	}
	pinnedHistory, err := p.historyRoot.Stat(".")
	if err != nil || !pinnedHistory.IsDir() || !os.SameFile(p.historyInfo, pinnedHistory) {
		return fmt.Errorf("%s: pinned history FTS directory changed during publication", memoryErrStateUnsafe)
	}
