		out[i].SessionID = sessionID
		id, degraded := conversationExchangeID(repoKey, sessionID, out[i].TurnOrdinal, out[i].RequestDigest, out[i].SourceDigest)
		out[i].ID = id
		out[i].IdentityDegraded = degraded
	}
	return out
}

