+func TestHistoryFTSDuplicateConversationIDsRemainDistinctRows(t *testing.T) {
+	sharedID := "conversation:shared-turn"
+	index := historyIndex{
+		GeneratedAt: time.Date(2026, 8, 20, 0, 0, 0, 0, time.UTC),
+		Records: []historyRecord{
+			{ID: sharedID, Kind: conversationKind, Branch: "main", Path: "sessions/main/first.jsonl", Line: 10, Summary: "Alpha conversation covers the shared retrieval marker."},
+			{ID: sharedID, Kind: conversationKind, Branch: "feature", Path: "sessions/feature/second.jsonl", Line: 20, Summary: "Beta conversation covers the shared retrieval marker."},
+		},
+	}
+	brainDir, source := writeDirectHistoryFTSFixture(t, index)
+
+	got, used, err := rankHistoryViaFreshFTSCutoff(brainDir, source, conversationKind, "shared retrieval marker", 10, 0)
+	if err != nil || !used {
+		t.Fatalf("direct duplicate-ID ranking: used=%v err=%v", used, err)
+	}
+	if len(got) != 2 {
+		t.Fatalf("duplicate conversation IDs collapsed or corrupted payload hydration: %+v", got)
+	}
+	orders := map[int]bool{}
+	branches := map[string]bool{}
+	for _, match := range got {
+		if match.Record.ID != sharedID {
+			t.Fatalf("unexpected hydrated ID: %+v", match)
+		}
+		orders[match.Order] = true
+		branches[match.Record.Branch] = true
+	}
+	if !orders[0] || !orders[1] || !branches["main"] || !branches["feature"] {
+		t.Fatalf("row-order/branch identity was not preserved: orders=%v branches=%v", orders, branches)
+	}
+
+	db, err := openHistoryFTSIfFresh(brainDir, index)
+	if err != nil || db == nil {
+		t.Fatalf("open duplicate-ID store: db=%v err=%v", db, err)
+	}
+	defer db.Close()
+	rows, err := db.Query(`SELECT fts_rowid, rec_order, id FROM history_records ORDER BY rec_order`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer rows.Close()
+	row := 0
+	for rows.Next() {
+		var ftsRowID, order int
+		var id string
+		if err := rows.Scan(&ftsRowID, &order, &id); err != nil {
+			t.Fatal(err)
+		}
+		if ftsRowID != order+1 || order != row || id != sharedID {
+			t.Fatalf("row integrity mismatch: rowid=%d order=%d id=%q", ftsRowID, order, id)
+		}
+		row++
+	}
+	if err := rows.Err(); err != nil {
+		t.Fatal(err)
+	}
+	if row != 2 {
+		t.Fatalf("stored payload rows=%d, want 2", row)
+	}
+}
