package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/spf13/cobra"
)

// history_eval.go is the history-layer retrieval eval — the measurement the
// Stage 1a findings left open ("tunable once a history eval lands"). It mirrors
// the facts eval (facts_eval.go / facts_eval_gen.go) and reuses its task,
// result, and summary machinery, so `facts eval-compare` works on history
// summaries unchanged. It exists to answer three questions the alignment plan
// gates on this eval:
//
//  1. The BM25 relevance cutoff and top-k (historyFTSRelevanceCutoff = 0.30 was
//     chosen by inspection) — sweep with --cutoff / --k.
//  2. Whether a semantic arm fused with the shipped BM25 lifts retrieval —
//     Model2Vec measured as noise on history prose, EmbeddingGemma separated
//     cleanly on the probe, but the quantitative lift was never measured. Run
//     --arm fused (optionally with ENTIRE_BRAIN_EMBEDDER=ollama) vs --arm bm25.
//  3. Whether history vectors are worth persisting in the vec0 store at all.
//
// Tasks are provenance-labeled, exactly like facts eval-gen: each captured
// session becomes a task (its opening user request), and the history records
// extracted FROM that session's transcript are the ground-truth relevant set.
// `request`-kind records are excluded from labels: the general ranking arm
// filters them out (they are the query restated), so counting them would cap
// recall on records the arm can never surface.

// --- task generation (history eval-gen) -------------------------------------

func newHistoryEvalGenCommand(opts Options) *cobra.Command {
	var (
		out        string
		limit      int
		branch     string
		minRecords int
		maxRecords int
		midtask    bool
	)
	cmd := &cobra.Command{
		Use:   "history-eval-gen",
		Short: "Generate a labeled history-retrieval task set from the brain's own sessions",
		Long: `history-eval-gen builds a provenance-labeled benchmark for the history layer:
each captured session becomes a task (its opening user request), and the history
records indexed from that session's transcript are the ground-truth relevant set.
Emits a tasks.json consumable by 'history-eval --tasks'.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			manifest, err := loadBrainManifest(brainDir)
			if err != nil {
				return err
			}
			if manifest.Sources == nil || manifest.Sources.Sessions == nil {
				return fmt.Errorf("no exported sessions; run `entire brain refresh` first")
			}
			index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
			if err != nil {
				return err
			}
			tasks := generateHistoryEvalTasksContext(cmd.Context(), brainDir, manifest, index, branch, minRecords, maxRecords, limit, midtask)
			if len(tasks) == 0 {
				return fmt.Errorf("no sessions qualified as tasks (need >= %d indexed records and a recoverable opening request)", minRecords)
			}
			data, err := json.MarshalIndent(tasks, "", "  ")
			if err != nil {
				return err
			}
			data = append(data, '\n')
			if strings.TrimSpace(out) == "" {
				_, err = cmd.OutOrStdout().Write(data)
				return err
			}
			if err := os.WriteFile(out, data, 0o600); err != nil {
				return err
			}
			fmt.Fprintf(cmd.ErrOrStderr(), "wrote %d tasks to %s\n", len(tasks), out)
			return nil
		},
	}
	cmd.Flags().StringVar(&out, "out", "", "Write tasks JSON to this file (default: stdout)")
	cmd.Flags().IntVar(&limit, "limit", 0, "Cap the number of tasks, sampled evenly across strata (0 = all)")
	cmd.Flags().StringVar(&branch, "branch", "", "Limit to sessions on one branch (default: all)")
	// History records are far denser per session than facts (~83 median on the
	// live brain vs the facts eval's 2-30 band): a session emits one record per
	// decision/validation/tool-path line, not one per durable insight. The
	// max-records cap therefore sits an order of magnitude above facts
	// eval-gen's max-facts.
	cmd.Flags().IntVar(&minRecords, "min-records", 2, "Minimum indexed records for a session to become a task")
	cmd.Flags().IntVar(&maxRecords, "max-records", 200, "Skip broad sessions with more records than this (diffuse targets); 0 = no cap")
	cmd.Flags().BoolVar(&midtask, "midtask", true, "Also mine mid-session follow-up questions as a 'midtask' stratum (labels: the records after each question)")
	return cmd
}

// queryTypeMidtask is the stratum for mid-session follow-up questions —
// an agent's real retrieval moments are narrow in-flight asks ("why does
// flush keep branches dirty under --force?"), not session-opening requests.
// Tasks in this stratum use the session's LATER request records as queries
// and the records that FOLLOW each question as ground truth: the answer to a
// mid-task question manifests in the work that came after it.
const queryTypeMidtask = "midtask"

// midtaskTasksPerSession caps the follow-up questions mined per session so a
// long interactive session cannot dominate the benchmark.
const midtaskTasksPerSession = 3

// generateHistoryEvalTasks maps each qualifying session to one provenance-
// labeled opening task plus up to midtaskTasksPerSession mid-task ones. A
// record is attributable to a session through its Path — the transcript file
// the record was extracted from — which equals the session's manifest
// TranscriptPath (both are slash-relative to the brain dir).
func generateHistoryEvalTasks(brainDir string, manifest *exportManifest, index historyIndex, branch string, minRecords, maxRecords, limit int, midtask bool) []evalTask {
	return generateHistoryEvalTasksContext(context.Background(), brainDir, manifest, index, branch, minRecords, maxRecords, limit, midtask)
}

func generateHistoryEvalTasksContext(ctx context.Context, brainDir string, manifest *exportManifest, index historyIndex, branch string, minRecords, maxRecords, limit int, midtask bool) []evalTask {
	type pathRecords struct {
		rankable []historyRecord // non-request records, the labelable set
		requests []historyRecord // request records, line-ordered below
	}
	byPath := map[string]*pathRecords{}
	seen := map[string]struct{}{}
	for _, r := range index.Records {
		if _, dup := seen[r.ID]; dup {
			continue
		}
		seen[r.ID] = struct{}{}
		pr, ok := byPath[r.Path]
		if !ok {
			pr = &pathRecords{}
			byPath[r.Path] = pr
		}
		switch {
		case r.Kind == "request":
			pr.requests = append(pr.requests, r)
		case historyGeneralRankingHiddenKind(r.Kind):
			// Conversation exchanges are hidden from general ranking, so they
			// cannot be labelable eval answers either.
		default:
			pr.rankable = append(pr.rankable, r)
		}
	}
	for _, pr := range byPath {
		sort.SliceStable(pr.requests, func(i, j int) bool { return pr.requests[i].Line < pr.requests[j].Line })
	}

	var tasks []evalTask
	withinBounds := func(n int) bool { return n >= minRecords && (maxRecords <= 0 || n <= maxRecords) }
	for _, s := range manifest.Sources.Sessions.Sessions {
		if branch != "" && s.Branch != branch {
			continue
		}
		pr := byPath[s.TranscriptPath]
		if pr == nil || !withinBounds(len(pr.rankable)) {
			continue
		}
		data, readErr := readCanonicalHistoryTranscript(ctx, brainDir, s.TranscriptPath)
		if readErr != nil {
			continue
		}
		content := string(data)
		request := firstUserRequest(content)
		if request == "" {
			continue
		}
		ids := make([]string, 0, len(pr.rankable))
		for _, r := range pr.rankable {
			ids = append(ids, r.ID)
		}
		sort.Strings(ids)
		tasks = append(tasks, evalTask{
			ID:          shortSessionID(s.SessionID),
			Task:        request,
			Branch:      s.Branch,
			QueryType:   classifyHistoryQueryType(request),
			Relevant:    ids,
			LabelSource: evalLabelSourceProvenanceSilver, // provenance-derived, never proof-grade
		})
		if midtask {
			tasks = append(tasks, midtaskEvalTasks(s, pr.requests, pr.rankable, minRecords, maxRecords)...)
		}
	}
	tasks = dedupeEvalTasks(tasks)
	sort.SliceStable(tasks, func(i, j int) bool { return tasks[i].ID < tasks[j].ID })
	if limit > 0 && len(tasks) > limit {
		tasks = sampleAcrossStrata(tasks, limit)
	}
	return tasks
}

// midtaskEvalTasks mines a session's follow-up questions: every request
// record past the opening one is a candidate query, labeled with the
// session's rankable records AFTER that question's line. Wrapper injections
// are filtered with the same predicate the opening request uses.
func midtaskEvalTasks(s exportSession, requests, rankable []historyRecord, minRecords, maxRecords int) []evalTask {
	var tasks []evalTask
	for i, req := range requests {
		if i == 0 || isWrapperRequest(req.Summary) {
			continue // the opening request is the session-level task's query
		}
		var ids []string
		for _, r := range rankable {
			if r.Line > req.Line {
				ids = append(ids, r.ID)
			}
		}
		if len(ids) < minRecords || (maxRecords > 0 && len(ids) > maxRecords) {
			continue
		}
		sort.Strings(ids)
		tasks = append(tasks, evalTask{
			ID:          fmt.Sprintf("%s-m%d", shortSessionID(s.SessionID), req.Line),
			Task:        req.Summary,
			Branch:      s.Branch,
			QueryType:   queryTypeMidtask,
			Relevant:    ids,
			LabelSource: evalLabelSourceProvenanceSilver, // provenance-derived, never proof-grade
		})
		if len(tasks) >= midtaskTasksPerSession {
			break
		}
	}
	return tasks
}

// classifyHistoryQueryType strata: code/howto/concept. The facts classifier's
// "convention" stratum keys off fact path scope, which has no history analog
// (record paths are transcript files, not code loci).
func classifyHistoryQueryType(task string) string {
	if hasStructuralCodeToken(task) {
		return queryTypeCode
	}
	lower := strings.ToLower(strings.TrimSpace(task))
	if hasAnyPrefix(lower, "where ", "how do i", "how should", "how can i", "add ", "implement ", "fix ", "wire ", "make ", "build ", "create ", "update ", "remove ") {
		return queryTypeHowto
	}
	return queryTypeConcept
}

// --- eval (history eval) -----------------------------------------------------

// historyEvalArm ranks the index for one query and returns the surfaced
// records, or an error when the arm's machinery is unavailable — an eval must
