func TestHistoryFTSPinnedDirectoryRejectsSwap(t *testing.T) {
	brainDir := t.TempDir()
	valid := ftsTestIndex()
	if _, ok, err := rankHistoryViaFTSDetailed(brainDir, valid, "decisions", "embedding", 10); err != nil || !ok {
		t.Fatalf("prime valid cache: ok=%v err=%v", ok, err)
	}
	replacement := ftsTestIndex()
	replacement.Records[0].Summary = "A replacement generation built through a pinned directory."
	historyPath := filepath.Join(brainDir, historyDirName)
	detached := filepath.Join(brainDir, historyDirName+"-detached")
	swapped := false
	var swapErr error
	originalBoundary := historyFTSPublishBoundary
	t.Cleanup(func() { historyFTSPublishBoundary = originalBoundary })
	historyFTSPublishBoundary = func(step string) error {
		if step != "before_marker_create" {
			return nil
		}
		if swapErr = os.Rename(historyPath, detached); swapErr != nil {
			return swapErr
		}
		if swapErr = os.Mkdir(historyPath, 0o700); swapErr != nil {
			_ = os.Rename(detached, historyPath)
			return swapErr
		}
		swapped = true
		return nil
	}
	err := withBrainWriteLock(brainDir, func() error {
		return publishHistoryFTSLocked(brainDir, replacement, historyFTSIdentityFromIndex(replacement))
	})
	historyFTSPublishBoundary = originalBoundary
	if swapErr != nil {
		t.Skipf("platform cannot swap an open pinned directory: %v", swapErr)
	}
	if !swapped {
		t.Fatal("directory-swap seam did not run")
	}
	if err == nil || !strings.Contains(strings.ToLower(err.Error()), "directory changed") {
		t.Fatalf("pinned directory swap was not rejected: %v", err)
	}
	if err := os.Remove(historyPath); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(detached, historyPath); err != nil {
		t.Fatal(err)
	}
	assertNoHistoryFTSBuildArtifacts(t, brainDir)
	if got, ok, err := rankHistoryViaFTSDetailed(brainDir, valid, "decisions", "embedding", 10); err != nil || !ok || len(got) == 0 {
		t.Fatalf("original cache did not survive directory swap: ok=%v matches=%v err=%v", ok, ftsExcerpts(got), err)
	}
}

