func TestHistoryFTSPinnedSidecarSwapFailsClosedAndRecovers(t *testing.T) {
	brainDir := t.TempDir()
	valid := ftsTestIndex()
	if _, ok, err := rankHistoryViaFTSDetailed(brainDir, valid, "decisions", "embedding", 10); err != nil || !ok {
		t.Fatalf("prime valid cache: ok=%v err=%v", ok, err)
	}
	replacement := ftsTestIndex()
	replacement.Records[0].Summary = "A replacement generation recovered from a sidecar swap."
	sidecar := historyFTSDBPath(brainDir) + "-wal"
	backup := sidecar + ".test-old"
	if err := os.WriteFile(sidecar, []byte("legacy WAL placeholder"), 0o600); err != nil {
		t.Fatal(err)
	}
	external := filepath.Join(t.TempDir(), "external-sidecar")
	externalBytes := []byte("external sidecar must remain untouched")
	if err := os.WriteFile(external, externalBytes, 0o600); err != nil {
		t.Fatal(err)
	}
	swapped := false
	var swapErr error
	originalBoundary := historyFTSPublishBoundary
	t.Cleanup(func() { historyFTSPublishBoundary = originalBoundary })
	historyFTSPublishBoundary = func(step string) error {
		if step != "before_remove_"+filepath.Base(sidecar) {
			return nil
		}
		if swapErr = os.Rename(sidecar, backup); swapErr != nil {
			return swapErr
		}
		if swapErr = os.Symlink(external, sidecar); swapErr != nil {
			_ = os.Rename(backup, sidecar)
			return swapErr
		}
		swapped = true
		return nil
	}
	err := withBrainWriteLock(brainDir, func() error {
		return publishHistoryFTSLocked(brainDir, replacement, historyFTSIdentityFromIndex(replacement))
	})
	historyFTSPublishBoundary = originalBoundary
	if swapErr != nil {
		t.Skipf("platform cannot create sidecar-swap fixture: %v", swapErr)
	}
	if !swapped || err == nil || !strings.Contains(strings.ToLower(err.Error()), "regular file") {
		t.Fatalf("pinned sidecar swap was not rejected: swapped=%v err=%v", swapped, err)
	}
	if _, err := openHistoryFTSReadOnly(brainDir); !errors.Is(err, errHistoryFTSPublicationPending) {
		t.Fatalf("marked sidecar swap did not fail closed: %v", err)
	}
	if err := os.Remove(sidecar); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(backup, sidecar); err != nil {
		t.Fatal(err)
	}
	if err := withBrainWriteLock(brainDir, func() error { return recoverHistoryFTSPublicationLocked(brainDir) }); err != nil {
		t.Fatalf("recover sidecar-swap publication: %v", err)
	}
	gotExternal, err := os.ReadFile(external)
	if err != nil || !reflect.DeepEqual(gotExternal, externalBytes) {
		t.Fatalf("external sidecar changed: bytes=%q err=%v", gotExternal, err)
	}
	assertNoHistoryFTSBuildArtifacts(t, brainDir)
	if got, ok, err := rankHistoryViaFTSDetailed(brainDir, replacement, "decisions", "replacement", 10); err != nil || !ok || len(got) == 0 {
		t.Fatalf("recovered replacement is unavailable: ok=%v matches=%v err=%v", ok, ftsExcerpts(got), err)
	}
}

