func resolveSessionsBrain(ctx context.Context, opts Options) (repoStorage, error) {
	target := agentSurfaceTarget(opts, nil)
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return repoStorage{}, err
	}
