func TestGetBatchCapsRequestSize(t *testing.T) {
	ids := make([]string, maxGetBatchIDs+1)
	for i := range ids {
		ids[i] = fmt.Sprintf("doc:%03d", i)
	}
	if _, _, err := getUnifiedBatch("", t.TempDir(), "main", ids); err == nil {
