func TestHistoryFTSRebuildDeterministic(t *testing.T) {
	brainDir := t.TempDir()
	index := ftsTestIndex()
	query := "supersede a fact during reconcile"

	first, ok := rankHistoryViaFTS(brainDir, index, "decisions", query, 25)
	if !ok {
