	writeFile(t, repo, "main.min.js", "!function(){"+strings.Repeat("var a=fn(1);a&&a();", 26000)+"}();")

	symbols, failures := streamMinifiedProbe(t, repo)
	if !slices.Contains(failures, "E_MINIFIED") {
