func typeScriptGenericCallSignatureEnds(trimmed string, inReturn bool) bool {
	if trimmed == "" {
		return true
	}
	if inReturn && trimmed == ">" {
		return true
	}
	if strings.HasSuffix(trimmed, "<") || strings.HasSuffix(trimmed, ",") {
		return false
	}
