	parseSrc := src
	entitySrc := src
	entityLineOffset := 0
	if spec.language == "Protocol Buffers" {
		prepared, original, lineOffset := prepareProtocolBuffersParseSource(content)
		parseSrc = []byte(prepared)
		entitySrc = []byte(original)
		entityLineOffset = lineOffset
	}
